// server.js
const express = require('express');
const crypto = require('crypto');
const mongoose = require('mongoose');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
require('dotenv').config();

const app = express();

app.use(helmet());
app.use(cors({
  origin: process.env.FRONTEND_URL,
  credentials: true
}));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

app.use(express.json());

mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

const paymentSchema = new mongoose.Schema({
  chargeId: { type: String, required: true, unique: true },
  userId: String,
  productId: String,
  amount: Number,
  currency: String,
  status: { type: String, enum: ['pending', 'confirmed', 'failed', 'expired'], default: 'pending' },
  coinbaseData: Object,
  createdAt: { type: Date, default: Date.now },
  confirmedAt: Date,
  metadata: Object
});

const Payment = mongoose.model('Payment', paymentSchema);

app.post('/api/create-charge', async (req, res) => {
  try {
    const { amount, currency, productId, userId, metadata } = req.body;

    if (!amount || !currency) {
      return res.status(400).json({ error: 'Hiányzó kötelező mezők' });
    }

    const chargeData = {
      name: metadata?.productName || 'Termék',
      description: metadata?.description || 'Vásárlás',
      pricing_type: 'fixed_price',
      local_price: {
        amount: amount.toString(),
        currency: currency
      },
      metadata: {
        userId: userId,
        productId: productId,
        ...metadata
      }
    };

    const response = await fetch('', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CC-Api-Key': process.env.COINBASE_API_KEY,
        'X-CC-Version': '2018-03-22'
      },
      body: JSON.stringify(chargeData)
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(`Coinbase API hiba: ${JSON.stringify(errorData)}`);
    }

    const charge = await response.json();

    const payment = new Payment({
      chargeId: charge.data.id,
      userId: userId,
      productId: productId,
      amount: amount,
      currency: currency,
      status: 'pending',
      coinbaseData: charge.data,
      metadata: metadata
    });

    await payment.save();

    res.json({
      success: true,
      chargeId: charge.data.id,
      hostedUrl: charge.data.hosted_url,
      addresses: charge.data.addresses,
      expiresAt: charge.data.expires_at,
      pricing: charge.data.pricing
    });

  } catch (error) {
    console.error('Charge létrehozási hiba:', error);
    res.status(500).json({ error: 'Fizetés létrehozása sikertelen', details: error.message });
  }
});

app.post('/api/webhook', async (req, res) => {
  try {
    const signature = req.headers['x-cc-webhook-signature'];
    const payload = JSON.stringify(req.body);

    const computedSignature = crypto
      .createHmac('sha256', process.env.COINBASE_WEBHOOK_SECRET)
      .update(payload)
      .digest('hex');

    if (signature !== computedSignature) {
      console.error('Érvénytelen webhook aláírás');
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const event = req.body;
    const chargeId = event.data?.id;

    if (!chargeId) {
      return res.status(400).json({ error: 'Hiányzó charge ID' });
    }

    const payment = await Payment.findOne({ chargeId: chargeId });

    if (!payment) {
      console.error(`Payment not found: ${chargeId}`);
      return res.status(404).json({ error: 'Payment not found' });
    }

    switch (event.type) {
      case 'charge:created':
        payment.status = 'pending';
        break;

      case 'charge:confirmed':
        payment.status = 'confirmed';
        payment.confirmedAt = new Date();
        console.log(`✅ Fizetés megerősítve: ${chargeId}`);
        await handleSuccessfulPayment(payment);
        break;

      case 'charge:failed':
        payment.status = 'failed';
        console.log(`❌ Fizetés sikertelen: ${chargeId}`);
        break;

      case 'charge:delayed':
        console.log(`⏳ Fizetés késik: ${chargeId}`);
        break;

      case 'charge:pending':
        console.log(`⏱️ Fizetés függőben: ${chargeId}`);
        break;

      default:
        console.log(`Ismeretlen esemény típus: ${event.type}`);
    }

    payment.coinbaseData = event.data;
    await payment.save();

    res.status(200).json({ received: true });

  } catch (error) {
    console.error('Webhook feldolgozási hiba:', error);
    res.status(500).json({ error: 'Webhook processing failed' });
  }
});

async function handleSuccessfulPayment(payment) {
  console.log('Sikeres fizetés feldolgozása:', {
    chargeId: payment.chargeId,
    userId: payment.userId,
    productId: payment.productId,
    amount: payment.amount,
    currency: payment.currency
  });
}

app.get('/api/payment/:chargeId', async (req, res) => {
  try {
    const { chargeId } = req.params;

    const payment = await Payment.findOne({ chargeId: chargeId });

    if (!payment) {
      return res.status(404).json({ error: 'Fizetés nem található' });
    }

    res.json({
      chargeId: payment.chargeId,
      status: payment.status,
      amount: payment.amount,
      currency: payment.currency,
      createdAt: payment.createdAt,
      confirmedAt: payment.confirmedAt
    });

  } catch (error) {
    console.error('Payment lekérési hiba:', error);
    res.status(500).json({ error: 'Hiba történt' });
  }
});

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Szerver fut: `);
});

module.exports = app;
