        <div class="product-card">
            <div class="product-name" id="productName">Prémium Csomag</div>
            <div class="product-price" id="productPrice">9990 HUF</div>
        </div>

        <form class="payment-form" id="paymentForm">
            <input type="email" id="email" placeholder="Email cím" required>
            <input type="text" id="name" placeholder="Teljes név" required>

            <button type="submit" class="btn-pay" id="payBtn">
                🚀 Fizetés indítása
            </button>
        </form>

        <div id="statusMessage"></div>
    </div>

    <div class="payment-modal" id="paymentModal">
        <div class="modal-content">
            <button class="close-modal" onclick="closeModal()">&times;</button>
