    <script>
        const API_URL = '';

        const productConfig = {
            id: 'premium_package',
            name: 'Prémium Csomag',
            price: 9990,
            currency: 'HUF',
            description: 'Teljes hozzáférés minden funkcióhoz'
        };

        document.getElementById('productName').textContent = productConfig.name;
        document.getElementById('productPrice').textContent = `${productConfig.price} ${productConfig.currency}`;

        let currentChargeId = null;
        let pollingInterval = null;

        document.getElementById('paymentForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const email = document.getElementById('email').value;
            const name = document.getElementById('name').value;
            const payBtn = document.getElementById('payBtn');

            payBtn.disabled = true;
            payBtn.textContent = 'Feldolgozás...';

            try {
                const response = await fetch(`${API_URL}/create-charge`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        amount: productConfig.price,
                        currency: productConfig.currency,
                        productId: productConfig.id,
                        userId: email,
                        metadata: {
                            productName: productConfig.name,
                            description: productConfig.description,
                            customerName: name,
                            customerEmail: email
                        }
                    })
                });

                if (!response.ok) {
                    throw new Error('Fizetés létrehozása sikertelen');
                }

                const data = await response.json();
                currentChargeId = data.chargeId;

                showPaymentModal(data);
                startPolling(data.chargeId);

            } catch (error) {
                showStatus('Hiba történt: ' + error.message, 'error');
            } finally {
                payBtn.disabled = false;
                payBtn.textContent = '🚀 Fizetés indítása';
            }
        });

        function showPaymentModal(paymentData) {
            const modal = document.getElementById('paymentModal');
            const modalContent = document.getElementById('modalContent');

            let addressesHtml = '<div class="crypto-addresses">';

            Object.keys(paymentData.addresses).forEach(crypto => {
                const address = paymentData.addresses[crypto];
                addressesHtml += `
                    <div class="address-item">
                        <div class="address-label">${crypto.toUpperCase()}</div>
                        <div>${address}</div>
                    </div>
                `;
            });

            addressesHtml += '</div>';

            modalContent.innerHTML = `
                <p>Küldd el a fizetést az alábbi címek bármelyikére:</p>
                ${addressesHtml}
                <p style="margin-top: 20px; color: #666; font-size: 14px;">
                    vagy
                </p>

                    Fizetés Coinbase Commerce-szel

                <div class="loader"></div>
                <p style="text-align: center; margin-top: 20px; color: #666;">
                    Várakozás a fizetésre...
                </p>
            `;

            modal.classList.add('active');
        }

        function closeModal() {
            const modal = document.getElementById('paymentModal');
            modal.classList.remove('active');
            if (pollingInterval) {
                clearInterval(pollingInterval);
            }
        }

        function startPolling(chargeId) {
            pollingInterval = setInterval(async () => {
                try {
                    const response = await fetch(`${API_URL}/payment/${chargeId}`);
                    const data = await response.json();

                    if (data.status === 'confirmed') {
                        clearInterval(pollingInterval);
                        closeModal();
                        showStatus('✅ Fizetés sikeres! Köszönjük a vásárlást!', 'success');
                        setTimeout(() => {
                            window.location.href = '/success.html';
                        }, 2000);
                    } else if (data.status === 'failed') {
                        clearInterval(pollingInterval);
                        closeModal();
                        showStatus('❌ Fizetés sikertelen. Kérjük, próbálja újra.', 'error');
                    }
                } catch (error) {
                    console.error('Polling hiba:', error);
                }
            }, 5000);
        }

        function showStatus(message, type) {
            const statusDiv = document.getElementById('statusMessage');
            statusDiv.className = `status-message status-${type}`;
            statusDiv.textContent = message;
            statusDiv.style.display = 'block';
        }

        window.addEventListener('beforeunload', () => {
            if (pollingInterval) {
                clearInterval(pollingInterval);
            }
        });
