class CoinbaseCommerceClient {
  constructor(apiKey) {
    this.apiKey = apiKey;
    this.baseUrl = '';
  }

  async createCharge(chargeData) {
    const response = await fetch(`${this.baseUrl}/charges`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CC-Api-Key': this.apiKey,
        'X-CC-Version': '2018-03-22'
      },
      body: JSON.stringify(chargeData)
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(`Coinbase API error: ${JSON.stringify(error)}`);
    }

    return await response.json();
  }

  async getCharge(chargeId) {
    const response = await fetch(`${this.baseUrl}/charges/${chargeId}`, {
      headers: {
        'X-CC-Api-Key': this.apiKey,
        'X-CC-Version': '2018-03-22'
      }
    });

    if (!response.ok) {
      throw new Error('Failed to fetch charge');
    }

    return await response.json();
  }

  async listCharges(limit = 25) {
    const response = await fetch(`${this.baseUrl}/charges?limit=${limit}`, {
      headers: {
        'X-CC-Api-Key': this.apiKey,
        'X-CC-Version': '2018-03-22'
      }
    });

    if (!response.ok) {
      throw new Error('Failed to list charges');
    }

    return await response.json();
  }
}

module.exports = CoinbaseCommerceClient;
